  width: 100%;
  padding: 0.5rem 1rem;
  border: none;
  border-radius: var(--radius);
  background: rgba(255, 255, 255, 0.1);
  color: var(--white);
  font-size: 0.875rem;
}

.search-bar input::placeholder {
  color: rgba(255, 255, 255, 0.6);
}

.nav-links {
  display: none;
