.learn-hero {
  background: var(--primary-dark);
  color: var(--white);
  padding: 3rem 1.5rem;
  text-align: center;
}

.learn-hero h1 {
  font-size: 2rem;
  font-weight: 700;
  margin-bottom: 1rem;
}

.learn-hero p {
  opacity: 0.8;
  max-width: 600px;
  margin: 0 auto 1.5rem;
}

.curriculum-grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: 1rem;
  max-width: 1200px;
  margin: 0 auto;
}

@media (min-width: 768px) {
  .curriculum-grid {
    grid-template-columns: repeat(2, 1fr);
  }
}

@media (min-width: 1024px) {
  .curriculum-grid {
    grid-template-columns: repeat(3, 1fr);
  }
}

.curriculum-card {
  background: var(--white);
  border: 1px solid var(--border-gray);
  border-radius: var(--radius-lg);
  padding: 1.5rem;
  display: flex;
  align-items: flex-start;
  gap: 1rem;
  transition: all var(--transition);
}

.curriculum-card:hover {
  border-color: var(--accent-gold);
  box-shadow: var(--shadow-md);
}

.curriculum-icon {
  width: 48px;
  height: 48px;
  background: var(--light-gray);
  border-radius: var(--radius);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.25rem;
  flex-shrink: 0;
}

.curriculum-card h3 {
  font-size: 1rem;
  font-weight: 600;
  color: var(--text-dark);
}

.daily-challenge {
  background: linear-gradient(135deg, var(--primary-dark), #1a1a40);
  color: var(--white);
  padding: 2.5rem;
  border-radius: var(--radius-lg);
  text-align: center;
  max-width: 800px;
  margin: 0 auto;
}

.daily-challenge h2 {
  font-size: 1.5rem;
  margin-bottom: 0.75rem;
}

.daily-challenge p {
  opacity: 0.8;
  margin-bottom: 1.5rem;
}

.daily-links {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: 1rem;
}

.section-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 1.5rem;
  padding: 0 1.5rem;
  max-width: 1200px;
  margin-left: auto;
  margin-right: auto;
}

.section-header h2 {
  font-size: 1.5rem;
  font-weight: 700;
}

/* Donate Page Styles */
.donate-hero {
  background: linear-gradient(135deg, var(--primary-dark) 0%, #1a1a40 100%);
  color: var(--white);
  padding: 4rem 1.5rem;
  text-align: center;
}

.donate-hero h1 {
  font-size: 2.5rem;
  font-weight: 800;
  margin-bottom: 1rem;
}

.donate-hero p {
  max-width: 600px;
  margin: 0 auto;
  opacity: 0.9;
  line-height: 1.7;
}

.donation-form {
  max-width: 600px;
  margin: -2rem auto 2rem;
  background: var(--white);
  border-radius: var(--radius-lg);
  padding: 2rem;
  box-shadow: var(--shadow-md);
  position: relative;
}

.amount-tabs {
  display: flex;
  gap: 0.5rem;
  margin-bottom: 1.5rem;
}

.amount-tab {
  flex: 1;
  padding: 0.75rem;
  border: 2px solid var(--border-gray);
  border-radius: var(--radius);
  background: var(--white);
  font-size: 1rem;
  font-weight: 600;
  cursor: pointer;
  transition: all var(--transition);
}

.amount-tab:hover {
  border-color: var(--primary-dark);
}

.amount-tab.active {
  background: var(--primary-dark);
  color: var(--white);
  border-color: var(--primary-dark);
}

.donation-description {
  background: var(--light-gray);
  padding: 1rem;
  border-radius: var(--radius);
  margin-bottom: 1.5rem;
  text-align: center;
  font-size: 0.95rem;
  color: var(--text-dark);
}

.donate-btn {
  width: 100%;
  padding: 1rem;
  background: var(--accent-gold);
  color: var(--primary-dark);
  border: none;
  border-radius: var(--radius);
  font-size: 1rem;
  font-weight: 700;
  cursor: pointer;
  transition: background var(--transition);
}

.donate-btn:hover {
  background: #e89b2e;
}

.donation-sublabel {
  text-align: center;
  margin-top: 0.75rem;
  font-size: 0.8rem;
  color: var(--text-muted);
}

.supporter-section {
  padding: 3rem 1.5rem;
  background: var(--light-gray);
}

.supporter-benefits {
  list-style: none;
  max-width: 600px;
  margin: 0 auto;
}

.supporter-benefits li {
  padding: 0.75rem 0;
  border-bottom: 1px solid var(--border-gray);
  display: flex;
  align-items: center;
  gap: 0.75rem;
}

.benefit-icon {
  width: 24px;
  height: 24px;
  background: var(--accent-gold);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--primary-dark);
  font-size: 0.75rem;
  flex-shrink: 0;
}

.initiatives-section {
  padding: 3rem 1.5rem;
}

.initiatives-list {
  list-style: none;
  max-width: 600px;
  margin: 0 auto;
}

.initiatives-list li {
  padding: 0.75rem 0;
  display: flex;
  align-items: flex-start;
  gap: 0.75rem;
}

.initiative-bullet {
  width: 8px;
  height: 8px;
  background: var(--accent-gold);
  border-radius: 50%;
  margin-top: 0.5rem;
  flex-shrink: 0;
}

.community-section {
  padding: 3rem 1.5rem;
  background: var(--primary-dark);
  color: var(--white);
}

.community-stats {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 1rem;
  max-width: 600px;
  margin: 0 auto;
}

@media (min-width: 768px) {
  .community-stats {
    grid-template-columns: repeat(2, 1fr);
  }
}

.stat-item {
  background: rgba(255, 255, 255, 0.1);
  padding: 1.5rem;
  border-radius: var(--radius);
  text-align: center;
}

.stat-value {
  font-size: 1.5rem;
  font-weight: 700;
  color: var(--accent-gold);
}

.stat-label {
  font-size: 0.85rem;
  opacity: 0.8;
  margin-top: 0.25rem;
}

.faq-section {
  padding: 3rem 1.5rem;
  max-width: 800px;
  margin: 0 auto;
}

.faq-item {
  border-bottom: 1px solid var(--border-gray);
}

.faq-question {
  width: 100%;
  padding: 1.25rem 0;
  background: none;
  border: none;
  text-align: left;
  font-size: 1rem;
  font-weight: 600;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
}

.faq-question:hover {
  color: var(--link-blue);
}

.faq-icon {
  font-size: 1.25rem;
  transition: transform var(--transition);
}

.faq-item.active .faq-icon {
  transform: rotate(45deg);
}

.faq-answer {
  max-height: 0;
  overflow: hidden;
  transition: max-height 300ms ease, padding 300ms ease;
}

.faq-item.active .faq-answer {
  max-height: 500px;
  padding-bottom: 1.25rem;
}

.faq-answer p {
  color: var(--text-muted);
  line-height: 1.7;
}
